items.solution:
function append(log, event) {
  const seq = log.length;
  const prevHash = seq === 0 ? "GENESIS" : log[seq - 1].hash;
  const hash = `h${seq}`;
  const stored = { ...event, seq, prevHash, hash };
  log.push(stored);
  return stored;
}

