items.solution:
function gateRecord(record, fields, grantedClassifications) {
  const result = {};
  for (const field of fields) {
    result[field.name] = grantedClassifications.includes(field.classification)
      ? record[field.name]
      : "[REDACTED]";
  }
  return result;
}

