items.solution:
function isPastDeadline(createdAtIso, retentionMonths, asOfIso) {
  const created = new Date(createdAtIso);
  const asOf = new Date(asOfIso);
  const elapsedMonths =
    (asOf.getFullYear() - created.getFullYear()) * 12 +
    (asOf.getMonth() - created.getMonth());
  return elapsedMonths >= retentionMonths;
}

